import{_ as o,o as r,c as e,ag as n}from"./chunks/framework.D5hoimZQ.js";const h=JSON.parse('{"title":"科技爱好者周刊 #414 提炼：Jev 决策模型 ｜ Markdown 正在变成源码","description":"","frontmatter":{"sidebar":true},"headers":[],"relativePath":"topics/ai-system-architecture/weekly-414-analysis.md","filePath":"topics/ai-system-architecture/weekly-414-analysis.md"}'),s={name:"topics/ai-system-architecture/weekly-414-analysis.md"};function a(i,t,d,g,l,u){return r(),e("div",null,[...t[0]||(t[0]=[n('<h1 id="科技爱好者周刊-414-提炼-jev-决策模型-markdown-正在变成源码" tabindex="-1">科技爱好者周刊 #414 提炼：Jev 决策模型 ｜ Markdown 正在变成源码 <a class="header-anchor" href="#科技爱好者周刊-414-提炼-jev-决策模型-markdown-正在变成源码" aria-label="Permalink to &quot;科技爱好者周刊 #414 提炼：Jev 决策模型 ｜ Markdown 正在变成源码&quot;">​</a></h1><blockquote><p>来源：阮一峰《科技爱好者周刊》第 414 期（封面：国产首列数字地铁列车 VELLINK，完全无人驾驶，车头改大幅玻璃用于观光） 原文链接：<a href="https://github.com/ruanyf/weekly/blob/master/docs/issue-414.md" target="_blank" rel="noreferrer">https://github.com/ruanyf/weekly/blob/master/docs/issue-414.md</a> 直链：<a href="https://raw.githubusercontent.com/ruanyf/weekly/master/docs/issue-414.md" target="_blank" rel="noreferrer">https://raw.githubusercontent.com/ruanyf/weekly/master/docs/issue-414.md</a> 抓取校验：2026-10-09 抓取成功，正文 389 行 / 19,900 字节，含标题「科技爱好者周刊（第 414 期）：Jev 决策模型有什么用」✅ 外部核实：TypeSafe AI 官方博客《Introducing System One Models &amp; Jev》（2026-09-15，作者 Diogo Almeida）+ Simon Willison《Jev introduces a new shape of LLM—System One, aka Decision Models》（2026-09-21）+ Carson Gross《Markdown in /src》（htmx.org，2026-09-21）+ Stephen A. Weis《RSA-896》（saweis.net，2026-09）+ Tymscar Blog《Ctrl+F Finds Words…》（2026-09-30）+ GitHub API 实测全部工具仓库 状态：已落盘 · 周刊监控第 4 期（上一期 #413）</p></blockquote><hr><h2 id="一、本期主文" tabindex="-1">一、本期主文 <a class="header-anchor" href="#一、本期主文" aria-label="Permalink to &quot;一、本期主文&quot;">​</a></h2><h3 id="_1-jev-决策模型有什么用" tabindex="-1">1. Jev 决策模型有什么用 <a class="header-anchor" href="#_1-jev-决策模型有什么用" aria-label="Permalink to &quot;1. Jev 决策模型有什么用&quot;">​</a></h3><p><strong>原文主张（阮一峰）</strong></p><ul><li>上个月最大的 AI 新闻不是 GPT / Claude 的新版本，而是一家名不见经传的公司 <strong>TypeSafe AI</strong> 发布的新类型模型 <strong>Jev</strong>，叫&quot;决策模型&quot;。</li><li>Jev 的最大特点：<strong>其他模型返回文字，它返回一个浮点数，表示概率</strong>。 <ul><li><strong>是非题</strong>：问世上一句陈述&quot;是否正确&quot;，返回 0~1 的置信度。</li><li><strong>选择题</strong>：给 ABCD 四个选项，返回每个选项正确的概率分布。</li><li><strong>评分题（score）</strong>：给一组评分标准 + 一篇原始材料，返回一个分数。</li></ul></li><li>周刊给两个真实例子（都是基于 Jev 的浏览器插件）： <ol><li><a href="https://blog.tymscar.com/posts/hunchsemanticfind/" target="_blank" rel="noreferrer">《我用 Ctrl + F 寻找答案》</a>：把 Ctrl+F 从&quot;找词&quot;改造成&quot;找答案&quot;——依次拿每个段落问 Jev&quot;本段是否与搜索词相关？&quot;，相关度最高的段落即语义查找结果。</li><li><a href="https://pub.towardsai.net/build-a-browser-extension-with-jev-22e026255cb7" target="_blank" rel="noreferrer">《我用 Jev 为网页打分》</a>：给 Jev 一组从低到高的评分标准，让它自动给新打开的网页打分，从而不读网页就知道内容质量。</li></ol></li><li>周刊的核心判断句：<strong>&quot;一旦 AI 模型返回量化的结果，许多以前无法数字化处理的问题，顿时都能用计算机处理了。&quot;</strong></li><li>周刊引 Simon Willison 的评价（一针见血）：&quot;Jev 实际上代表着机器学习系统的倒退，走向黑箱系统…… Jev 甚至连&#39;解释&#39;都不给你：你只会得到一个浮点数，这个数字是怎么来的，不知道。&quot;并担忧有人用 Jev 给求职者排名。</li></ul><p><strong>外部核实（把转述钉成事实）</strong></p><p>我把一手原文都抓下来了，周刊的转述总体准确，以下是更精的版本：</p><table tabindex="0"><thead><tr><th>项目</th><th>核实结果</th></tr></thead><tbody><tr><td>发布方 / 时间 / 作者</td><td>✅ TypeSafe AI，2026-09-15 博客《Introducing System One Models &amp; Jev》，作者是 <strong>创始人 Diogo Almeida</strong>（自称在 OpenAI 参与过让语言模型&quot;听懂指令、能对话&quot;的方法研究，&quot;那项工作后来成了 ChatGPT 背后的研究&quot;），<strong>潜伏两年</strong>后发布</td></tr><tr><td>定位</td><td>✅ &quot;System One Model&quot;，选输出是 <strong>typed probabilistic decisions（带类型的概率决策）</strong>；官方原话是 <strong>&quot;frontier-intelligence function call: unstructured state in, typed probabilistic decisions out&quot;</strong>——把 Jev 类比成一次&quot;前沿智能的函数调用&quot;</td></tr><tr><td>三种问法</td><td>✅ 是非题（官方叫 <strong>Noul</strong>，CEO 在 Hacker News 确认是 <strong>Bernoulli 分布</strong>的缩写，非&quot;no/yes&quot;）、选择题（返回<strong>置信度 + 全选项概率分布</strong>）、评分题；一个 state 可同时塞多个问题、<strong>并行求值</strong></td></tr><tr><td>性能 / 训练</td><td>✅ 官方称&quot;System One 任务上智力接近现有 LLM，但<strong>快两个数量级、更省</strong>&quot;；<strong>放弃字符串生成 → 不能幻觉</strong>；训练法是自创的 <strong>RLCD（Reinforcement Learning for Calibrated Decisions）</strong>，区别于 RLHF / RLVR</td></tr><tr><td>价格</td><td>✅（Simon Willison 核实）<strong>只按输入计费、输出免费</strong>，首模型 <strong>$0.042 / 百万 token</strong>，比 OpenAI GPT-5 Nano（$0.05/M）还便宜</td></tr><tr><td>Willison 的批评</td><td>✅ 确有原文，周刊翻译准确。英文原句 &quot;…represents a regression even further towards black box machine learning systems… the only thing you&#39;re going to get back is a floating point number. If Jev marks something as spam, <strong>which content signals tipped it off?</strong>&quot; 他还做了一个实验：让 Jev 给湾区各城市打&quot;Good city?&quot;的分，<strong>Cupertino 最高、East Palo Alto 最低</strong>——他注：&quot;Huh.&quot;（这个排名本身就暴露了隐藏偏见）</td></tr><tr><td>第二例文章</td><td>⚠️ towardai（Medium）被 Cloudflare 拦截（HTTP 403），<strong>未能直接核实</strong>；第一例（Tymscar《Ctrl+F Finds Words…》2026-09-30，作者 Oscar Molnar，工具名 <strong>Hunch</strong>）✅ 已核实</td></tr></tbody></table><p><strong>Willison 文中还有周刊没提、但很值钱的补充</strong>：</p><ul><li>Jev 的&quot;锯齿&quot;（jaggedness）：<strong>目前不擅长数字、日期和&quot;对抗性内容&quot;</strong>（官方文档自承）。</li><li>最好的用法是<strong>凡能表达成分类任务的场景</strong>：垃圾邮件识别、打标签、排序、优先级；他自己在试<strong>搜索重排（reranking）</strong>——先用 BM25 等便宜算法取 100 个候选，再让 Jev 逐个打相关性分。</li><li>生态在一周内爆发：开源权重复刻 <strong>Kev</strong>（基于 Qwen 3.5 出 0.8B / 4B / 9B）、<strong>JevBench</strong> 基准、<code>llm-typesafe</code> 插件，以及一堆玩梗项目（用 Jev 实现 left-pad、下 2048、甚至当&quot;糟糕的聊天模型&quot;）。</li></ul><p><strong>我的评注</strong></p><ol><li><strong>Jev 的本质是&quot;把开放式生成压成一次分类/打分&quot;</strong>——即<strong>表征降维</strong>。它没有发明新智能，而是把 LLM 塞回<strong>传统机器学习的接口</strong>：<code>unstructured in → typed out</code>。妙就妙在，一旦输出是浮点数，<strong>一切下游软件不需要&quot;解析自然语言&quot;就能消费它</strong>，于是&quot;以前无法数字化的判断&quot;被拉进了可编程世界。这不是智能的进步，是<strong>接口的退让</strong>——用可解释性换可组合性。</li><li><strong>它与本知识库自己的方法论直接撞车又互补</strong>。库内 <code>brain-self-evolution.md</code>（replay_eval）做的就是&quot;<strong>用冻结历史给策略打浮点分</strong>&quot;，而它暴露的最大 bug 恰恰是：<strong>一个浮点数掩盖了判断依据</strong>——打分器分不清&quot;助手凑数&quot;和&quot;助手实质&quot;。Jev 把这件事产品化了：便宜到能跑成千上万次实验，但<strong>你永远不知道那个 0.87 是怎么来的</strong>。Willison 的城市打分实验（Cupertino top / East Palo Alto bottom）就是活证据：<strong>偏见不会报错，它只会以一个漂亮的浮点数出现。</strong></li><li><strong>对用户的直接价值</strong>：外脑的 <code>semantic_search.py</code> / <code>query_brain.py</code> 目前是关键词/语义匹配，<strong>Jev 式的&quot;BM25 粗召回 + 决策模型精重排&quot;正是现成的升级路径</strong>——把&quot;这条记忆与查询相关吗&quot;变成一个可批量、可缓存的浮点分。但记住 Willison 的警告：<strong>凡涉及给人/给内容排名，浮点数会把偏见藏起来</strong>，这类裁定必须留人的眼睛复核（和 replay_eval 的教训同一条）。</li></ol><h3 id="_2-markdown-正在变成源码" tabindex="-1">2. Markdown 正在变成源码 <a class="header-anchor" href="#_2-markdown-正在变成源码" aria-label="Permalink to &quot;2. Markdown 正在变成源码&quot;">​</a></h3><p><strong>原文主张（阮一峰）</strong></p><ul><li>Markdown 以前只用于写文档；htmx 的作者提出一个大胆命题：<strong>Markdown 正在变成源码</strong>。</li><li>三条理由：（1）纯文本，diff / 搜索 / 审查都容易；（2）AI 像母语一样读写 Markdown；（3）人类无需工具即可读写。</li><li>推论：既然代码是 AI 根据 Markdown 提示词生成的，<strong>Markdown 提示词就该和生成的源码一起提交到 <code>/src</code> 目录</strong>。</li><li>事实佐证：Markdown 已经以 <code>AGENTS.md</code> 的形式成了源码的一部分。&quot;以后我们必须习惯，Markdown 文档也是源码。&quot;</li></ul><p><strong>外部核实</strong></p><p>原文是 Carson Gross（htmx 作者、蒙大拿州立大学教授）2026-09-21 的随笔《Markdown in /src》（htmx.org/essays）。比周刊转述更细：</p><ul><li><strong>TLDR</strong>（原文）：&quot;Markdown is becoming source code, not documentation；它应被 checkin 到 <code>/src</code>，<strong>挨着它生成的代码</strong>；代码与测试应<strong>从 Markdown 派生</strong>，而非从&quot;一次性的提示词&quot;派生。&quot;</li><li><strong>核心论证</strong>：LLM 常被类比为&quot;编译器&quot;（把高层规格编译成低层实现）——但编译器工作流<strong>保留源码</strong>，而当下 LLM 工作流<strong>不保留</strong>：代码是由一串临时 prompt 喂给 agent 生成的，<strong>结果代码本身成了唯一的&quot;ground truth&quot;</strong>，而意图散落在 Linear / Slack / wiki 里。Gross 主张：把 Markdown 提升到 <code>/src/md</code>，记录<strong>架构决策 / 源码级决策 / 低层数据设计决策</strong>——比传统设计文档低一层、更接近&quot;规格（spec-ish）&quot;。</li><li><strong>&quot;局部性（locality）&quot;是主论点</strong>：Markdown 放进 <code>/src</code>，好处是<strong>模块自带解释其意图的 Markdown</strong>，没有&quot;远处的规格（specification at a distance）&quot;，人和 agent 都不必再去别处找上下文。</li><li><strong>对&quot;测试即规格&quot;的回应</strong>：Gross 认为测试不是好的人机交互媒介（太多仪式感、层次太低、放不进 Mermaid 图），于是提出分工——<strong>Markdown 在 <code>/src</code> 当（准）规格，测试在 <code>/test</code> 基于 Markdown 提供自动正确性确认</strong>。</li><li>他引用了 Hartley Brody《Markdown is the new source code》作为先声。</li></ul><p><strong>我的评注</strong></p><ul><li>这条直接<strong>给本知识库外脑的存在合理性盖章</strong>：外脑存的 Markdown，本质就是&quot;<strong>意图的源码</strong>&quot;——它记录的不是&quot;结论是什么&quot;，而是&quot;为什么这么判断&quot;。<code>AGENTS.md</code>、<code>HEARTBEAT.md</code>、各 <code>topics/*/index.md</code> 全是同一个范式。</li><li>但要提防一个反噬：<strong>源码必须真的是 ground truth，不能是事后补写的文档</strong>。一旦 Markdown 变成&quot;代码写完后补的说明&quot;，它就退化成传统文档，diff 出来的只是噪声。所以这条路成立的前提是<strong>先写 Markdown（规格），再从中派生代码/测试</strong>——顺序反了就没意义。这与 #413 的&quot;代码即债务&quot;&quot;糊状千层面（分层＝可替换）&quot;是同一枚硬币：<strong>规范层的价值，取决于它是否真的在被消费。</strong></li><li>与库内 <code>llm-wiki-gbrain-knowledge-paradigm.md</code>（Karpathy 式 Compiled Truth + Timeline）严丝合缝：<strong>Compiled Truth 就是&quot;源码&quot;，Timeline 就是&quot;提交历史&quot;</strong>——Markdown-as-source 是这套架构的工程化身。</li></ul><hr><h2 id="二、本期简讯" tabindex="-1">二、本期简讯 <a class="header-anchor" href="#二、本期简讯" aria-label="Permalink to &quot;二、本期简讯&quot;">​</a></h2><h3 id="_3-不能摄像的摄像头-苹果" tabindex="-1">3. 不能摄像的摄像头（苹果） <a class="header-anchor" href="#_3-不能摄像的摄像头-苹果" aria-label="Permalink to &quot;3. 不能摄像的摄像头（苹果）&quot;">​</a></h3><p>据 theapplepost 报道，苹果将发布一款智能家居摄像头，<strong>最奇特处：它是摄像头但不录视频</strong>。完全靠 AI 分析环境、报告检测到的内容（如&quot;有陌生人敲门&quot;），只给<strong>详细文字描述</strong>而非视频。周刊的疑问：文字方便处理，但入室盗窃、包裹被盗等场景<strong>确实需要视频证据</strong>，苹果怎么处理？</p><ul><li><strong>我的评注</strong>：这是&quot;AI 把连续信号压成摘要&quot;的又一个样本——<strong>和主文一的 Jev、和 #413 的&quot;魔法师时代&quot;是同一个结构问题</strong>：连续、可回看的原始信号（视频/像素）被替换成离散、方便消费的摘要（文字/浮点数），代价是<strong>原始证据被丢弃 → 事后验证不可能</strong>。摄像头不录像的那一刻，它就不再是&quot;记录设备&quot;，而是一个&quot;在替你下判断的黑箱&quot;。当判断出错（把快递员判成入侵者、或漏判），你连回看的素材都没有。</li><li>关联 <code>cognitive-atrophy-knowledge.md</code>（System 0 / 判断外包）、<code>llm-reasoning-verification-thermodynamic.md</code>（可审计验证）。</li></ul><h3 id="_4-rsa-因素分解的新纪录" tabindex="-1">4. RSA 因素分解的新纪录 <a class="header-anchor" href="#_4-rsa-因素分解的新纪录" aria-label="Permalink to &quot;4. RSA 因素分解的新纪录&quot;">​</a></h3><ul><li>周刊：RSA 破解难度＝公钥能否被因数分解；密钥位越多越难破，<strong>此前最高纪录 768 位</strong>。2026 年 9 月，Anthropic 一位软件工程师<strong>借助 Claude</strong>，破解了 <strong>896 位</strong> RSA 密钥，并公布密钥与两个质因子。据其透露：用 Claude 把质因数分解库 <strong>CADO-NFS 移植到 GPU</strong>，在 <strong>2048 个 GPU 上跑了 10 天</strong>得到结果。启示：&quot;一个个人就能调用资源破解这么长的密钥，大机构能破解多少位？&quot;结论：<strong>RSA 密钥最少要 2048 位</strong>。</li><li><strong>外部核实</strong>：原文是 Stephen A. Weis 的《RSA-896》（saweis.net，2026-09）。关键细节比周刊更准，且<strong>周刊有一处需要修正</strong>： <ul><li>✅ Weis 自述：是他<strong>在 Anthropic 的集群</strong>上完成的——&quot;orchestrated running on a fleet of <strong>up to 2048 GPUs as a low-priority job</strong> during unused idle time&quot;，<strong>10 天约合 30 GPU-年</strong>的算力。</li><li>⚠️ <strong>周刊&quot;一个个人就能调用资源&quot;的叙事要打折</strong>：他调用的不是个人算力，而是<strong>大机构（Anthropic）闲置时的数据中心级 GPU 集群</strong>。真实图景不是&quot;个人变强了&quot;，而是&quot;<strong>大机构的闲置算力 + LLM 降低工程门槛</strong>&quot;两者叠加。</li><li>✅ Weis 明确：<strong>这次没有实质改进 GNFS 算法本身，也不影响已部署的 RSA-2048 的安全性</strong>；但它<strong>证明 RSA-1024 对拥有数据中心级 GPU 的行为者已不安全</strong>。</li><li>✅ 周刊&quot;此前纪录 768 位&quot;属实（RSA-768 是 2009 年著名结果）；位数从 768→896 成立。</li></ul></li><li><strong>我的评注</strong>：这条的启示不是&quot;加密被破了&quot;，而是 <strong>LLM 作为&quot;工程杠杆&quot;</strong>：把&quot;把一套科学计算库从 CPU 移植到 GPU&quot;这种苦活变得可行，于是<strong>门槛从&quot;算法突破&quot;降到&quot;算力 + 一点点工程&quot;</strong>。这与 #413 的&quot;AI 最先吃掉翻译层&quot;同源——<strong>LLM 最擅长的正是这种跨平台的机械移植（CADO-NFS → GPU）</strong>。对用户的直接含义：<strong>任何自建服务的密钥长度、哈希参数，都该按&quot;对手有数据中心 GPU&quot;来设下限</strong>，而不是按&quot;个人算力&quot;。</li><li>关联 <code>topics/cybersecurity/</code>、<code>llm-reasoning-verification-thermodynamic.md</code>（LLM 辅助科学计算）。</li></ul><hr><h2 id="三、文章" tabindex="-1">三、文章 <a class="header-anchor" href="#三、文章" aria-label="Permalink to &quot;三、文章&quot;">​</a></h2><ol><li><strong>JavaScript 技术栈 2026 最新动态</strong>（blog.master.dev）—— CodePen / CSS-Tricks 创始人 <strong>Chris Coyier</strong> 写的 JS 技术栈年度综述（语法、运行时、框架、工具），周刊推荐。</li><li><strong>我从 Deno 转投 Node.js</strong>（dbushell.com，2026-10-03）—— 作者对 Deno 失望，认为项目已失败，反而 Node.js 变得更好用。也是&quot;中间层/新运行时被旧生态反超&quot;的又一例。</li><li><strong>example.com 更改页面的解释</strong>（oliverdunk.com，2026-09-30）—— example.com 这个多年不变的示例页最近突然变动，本文讲清是谁架设、为何更改（IANA 答复相关）。</li><li><strong>AI 竞赛变得尴尬起来</strong>（insufferable.dev）—— 认为最近 <strong>Opus 5.5 与 GPT 6.1 Sol 降价</strong>，是因为两家<strong>偷偷用了 DeepSeek 的开源成果</strong>。（与本期言论 4 的 stratechery 观点是同一话题的两面）</li><li><strong>C 语言的灵活整数大小不是设计失误</strong>（pikuma.com）—— 解释为何 C 的 <code>int</code> 可以是 2 字节也可以是 4 字节，是移植性设计而非失误。</li><li><strong>我如何让一个二维码指向两个应用商店</strong>（matthuggins.com）—— 一张纸质卡片只印一个二维码，靠服务器后端识别扫码手机是安卓还是苹果并重定向到各自商店。<strong>实用小技巧</strong>，做产品落地页/卡片时可直接抄。</li></ol><hr><h2 id="四、工具-含-github-实测与接入评估" tabindex="-1">四、工具（含 GitHub 实测与接入评估） <a class="header-anchor" href="#四、工具-含-github-实测与接入评估" aria-label="Permalink to &quot;四、工具（含 GitHub 实测与接入评估）&quot;">​</a></h2><p>全部用 GitHub API 实测（2026-10-09）。★ = 对用户现有工作流（知识库外脑 / 飞书 / 风电与 PyPSA 仿真 / DSH / 自托管）的接入价值。</p><table tabindex="0"><thead><tr><th>工具</th><th>实测数据</th><th>一句话</th><th>接入价值</th></tr></thead><tbody><tr><td><a href="https://github.com/Qsnh/skillsgist" target="_blank" rel="noreferrer">skillsgist</a></td><td>TypeScript · <strong>9★</strong> · MIT · 建 <strong>2026-09-22</strong>（极新）· 活跃</td><td>基于 Cloudflare Worker 的<strong>私有 Skill 仓库</strong>，下载 Skill 需口令，供小团队内部使用</td><td>⭐ <strong>高（与用户的 Hermes skills 体系直接对位）</strong>。可参考其&quot;口令门控 + 私有分发&quot;模式，做一个内部/个人的 Skill 分发点。<strong>⚠️ 项目仅存续两周、9★，生产慎用</strong>，重在借思路</td></tr><tr><td><a href="https://github.com/leemysw/yovoice" target="_blank" rel="noreferrer">yovoice</a></td><td>TypeScript · <strong>420★</strong> · Apache-2.0 · 建 2026-09-15 · 活跃</td><td>桌面<strong>本地 TTS</strong> 配音工具，支持<strong>音色复刻 + 情绪调节</strong>，按文稿生成配音，<strong>全程本地</strong></td><td>⭐ <strong>中高</strong>。可把外脑日报/周刊提炼/知识点<strong>转成语音</strong>（通勤听知识库）。本地生成＝隐私可控。与库内 TTS 线（如 Voicebox 类）同域</td></tr><tr><td><a href="https://github.com/anghunk/video-transcript" target="_blank" rel="noreferrer">Video Transcript</a></td><td>TypeScript · <strong>28★</strong> · MIT · 建 2026-09-23</td><td>识别视频语音并<strong>自动加字幕</strong>的 Web 应用，<strong>本地模型</strong>完成，视频/字幕/导出均本地</td><td>⭐ <strong>中</strong>。用户常沉淀科普视频/周刊视频，此工具可把视频先转字幕再喂给外脑。另有同类 <a href="https://github.com/open-subs/opensubs" target="_blank" rel="noreferrer">OpenSubs</a></td></tr><tr><td><a href="https://github.com/elliothux/open-compute" target="_blank" rel="noreferrer">open-compute</a></td><td>Rust · <strong>1781★</strong> · Apache-2.0 · 建 2026-08-23 · 活跃</td><td><strong>Cloudflare Workers 的开源兼容平台</strong>，worker 脚本不改就能跑在自己机器上</td><td>⭐ <strong>中（自托管线）</strong>。想&quot;去 Cloudflare 化&quot;、把 worker 逻辑收回自托管的现成方案。1781★ 热度高、Apache 宽松</td></tr><tr><td><a href="https://github.com/aozorae/Edgechat" target="_blank" rel="noreferrer">EdgeChat</a></td><td>JavaScript · <strong>790★</strong> · <strong>GPL-3.0</strong> · 建 2026-04-05 · 活跃</td><td>基于 Cloudflare 的<strong>开源自部署聊天系统</strong>，群聊+私信，<strong>可与 Telegram 群组双向同步</strong></td><td>中（自托管线）。<strong>⚠️ GPL-3.0 传染</strong>；与飞书无直接关系，但&quot;自托管 + IM 双向同步&quot;架构可参考。237 fork 说明社区活跃</td></tr><tr><td><a href="https://github.com/ArkGravity/burrow" target="_blank" rel="noreferrer">Burrow</a></td><td>Go · <strong>9★</strong> · MIT · 建 2026-09-28（极新）</td><td>面向小团队/自托管的<strong>轻量 OIDC 单点登录</strong>，密码+验证器登录，走 OpenID Connect</td><td>中（自托管线）。给自建的一堆服务加统一登录的轻量方案。<strong>⚠️ 项目仅 10 天龄</strong>，概念先行</td></tr><tr><td><a href="https://github.com/aixisstudio/Snitch" target="_blank" rel="noreferrer">Snitch</a></td><td>开源 · 活跃</td><td><strong>实时网络流量可视化</strong>：查看电脑建立的每个连接、什么程序在与谁通信</td><td>中。DSH / 本地服务排障时看&quot;谁在往外发数据&quot;，与 AI IP 检测（#413）互补</td></tr><tr><td><a href="https://github.com/munvard/dockterm" target="_blank" rel="noreferrer">DockTerm</a></td><td>TypeScript · <strong>12★</strong> · MIT · 活跃</td><td>让 <strong>Claude Code 的权限请求从 Mac 刘海弹出</strong>，方便后台工作</td><td>中。用户跑 Claude Code（vibe-coding）时的体验优化</td></tr><tr><td><a href="https://github.com/CleanIP/sh.cd" target="_blank" rel="noreferrer">sh.cd</a></td><td>TypeScript · <strong>41★</strong> · MIT · 活跃</td><td><strong>服务器体检脚本</strong>：检查硬件、性能、IP 质量、网络质量</td><td>中高（自托管排障）。`curl sh.cd</td></tr><tr><td>其余</td><td><a href="https://getartcraft.com/apps" target="_blank" rel="noreferrer">Crafting Apps</a>（AI 用 Rust 重写 Adobe 七件套，全开源，<a href="https://github.com/storytold/photocraft" target="_blank" rel="noreferrer">PhotoCraft</a> 界面酷似 PS）、<a href="https://developer.apple.com/pass-designer/" target="_blank" rel="noreferrer">Pass Designer</a>（苹果官方二维码卡片设计）、<a href="https://github.com/lyuangg/tui-dashboard" target="_blank" rel="noreferrer">tui-dashboard</a>、<a href="https://github.com/byrencheema/airstats" target="_blank" rel="noreferrer">AirStats</a>、<a href="https://github.com/DayuanJiang/PecoFence" target="_blank" rel="noreferrer">PecoFence</a>、<a href="https://github.com/Kuddev/pebrel" target="_blank" rel="noreferrer">Pebrel</a>、<a href="https://github.com/WallpaperMachine/WallpaperMachine" target="_blank" rel="noreferrer">WallpaperMachine</a>、<a href="https://github.com/gentpan/LiteZip" target="_blank" rel="noreferrer">LiteZip</a>、<a href="https://github.com/corvofeng/atv-core" target="_blank" rel="noreferrer">atv-core</a></td><td>多为尝鲜/个人体验类</td><td>低（按需）</td></tr></tbody></table><p><strong>小结（工具层判断）</strong>：本期对用户真正有增量的是 <strong>skillsgist（借&quot;私有 Skill 分发&quot;思路）+ yovoice（知识转语音）+ Video Transcript（视频→字幕→外脑）</strong>，外加自托管线的 <strong>open-compute（去 Cloudflare 化）</strong>。老规矩两条提醒仍然生效：<strong>① 自托管 = 先查许可证</strong>（本期 EdgeChat 是 GPL-3.0 强传染）；<strong>② 极新项目（skillsgist 2 周、Burrow 10 天）= 先借思路、别上生产。</strong></p><hr><h2 id="五、资源" tabindex="-1">五、资源 <a class="header-anchor" href="#五、资源" aria-label="Permalink to &quot;五、资源&quot;">​</a></h2><ol><li><strong><a href="https://github.com/guokaigdg/naive-icons" target="_blank" rel="noreferrer">Naive Icons</a></strong> —— 手绘风格的 React SVG 图标库。</li><li><strong><a href="https://yueguwen.com/" target="_blank" rel="noreferrer">阅古文</a></strong> —— 免费古籍阅读站，除传统注释外可<strong>选中文本让 AI 解读</strong>。&quot;古籍 + AI 贴身注解&quot;是 AI 落地的漂亮场景（AI 弱化&quot;查工具书&quot;的门槛）。</li><li><strong><a href="https://artmuseum.artfrompixels.com/" target="_blank" rel="noreferrer">艺术史步行之旅</a></strong> —— 把维基百科上的画作按艺术流派做成<strong>可步行参观的 3D 画廊</strong>。与库内 <code>topics/design/</code>、表征/沉浸式知识呈现相关。</li><li><strong><a href="https://stillwet.art/" target="_blank" rel="noreferrer">stillwet</a></strong> —— AI 生成油画，<strong>模仿人类笔触一笔笔绘制</strong>，肉眼难辨。是&quot;AI 模仿过程而非直接出结果&quot;的样本（与 #413 的&quot;糊状千层面&quot;无关，但与&quot;AI 生成内容的水位&quot;有关）。</li></ol><hr><h2 id="六、图片" tabindex="-1">六、图片 <a class="header-anchor" href="#六、图片" aria-label="Permalink to &quot;六、图片&quot;">​</a></h2><ol><li><strong>旧金山有轨电车</strong> —— 旧金山许多古老有轨电车长期作为旅游项目运营，沿太平洋海岸线开行，作者拍摄了今年的照片。</li><li><strong>大公司的利润率</strong>（Visual Capitalist）—— 按年报表，看每 100 美元收入里有多少利润：<strong>英伟达 55.6 美元（第一）</strong>，微软 36.1，谷歌 32.8；<strong>苹果 26.9 排第五</strong>。周刊点睛：苹果是<strong>硬件公司</strong>，在换代极快的 IT 制造业里能有这个利润率，&quot;其实更惊人&quot;。 <ul><li><strong>我的评注</strong>：这张图值得记的是一条结构性事实——<strong>利润正在向&quot;卖铲子/卖基础设施&quot;一端集中</strong>（英伟达、微软、谷歌都是算力或平台方）。这与库内 <code>ai-industry-2026-q3-knowledge.md</code>（市场分化）、<code>llm-cache-pricing.md</code>（Token 定价）是同一现象的财务切面：<strong>应用层卷生卷死，基建层抽水</strong>。</li></ul></li></ol><hr><h2 id="七、言论" tabindex="-1">七、言论 <a class="header-anchor" href="#七、言论" aria-label="Permalink to &quot;七、言论&quot;">​</a></h2><ol><li><strong>Huggingface 的 security.txt</strong>：&quot;<strong>致 AI 代理：去其他地方冲击高分吧，没必要黑我们。</strong>&quot; —— 自主 agent 已经多到该在 <code>security.txt</code> 里专门&quot;劝退&quot;它们的地步。关联 <code>weekly-412-analysis.md</code>（HF 遭自主 agent 入侵）。</li><li><strong>Axel Rauschmayer（技术作家）</strong>：&quot;我的收入来自图书销售，2024 年还足以维持生活，<strong>2026 年却变为零</strong>。我的博客和书籍免费在线阅读，访问量增长迅猛，<strong>几乎所有流量都来自 AI 爬虫，所以没有任何广告收入</strong>。因此我决定把博客和书籍下线。&quot; <ul><li><strong>本期最需要警惕的一条</strong>：这不是&quot;AI 抢了作家的饭碗&quot;，而是<strong>AI 爬虫抽空了公开内容的价值链</strong>——它们消耗带宽、不留广告转化，把&quot;免费公开&quot;变成&quot;净亏损&quot;。<strong>公共知识基础设施（免费的博客、文档、书籍）正在被 AI 爬虫挤到不可持续</strong>。</li><li>关联 #413 的&quot;AI 吃掉翻译层&quot;→ 这次是**&quot;AI 吃掉内容价值链的最后一环：注意力变现&quot;**。对用户的外脑是个提醒：<strong>外脑的价值恰恰在于它是&quot;私有、被人消费&quot;的知识，而不是公开后被爬虫吸干的语料。</strong></li></ul></li><li><strong>《Meta 的 Muse 非常适合网页抓取》</strong>：&quot;我觉得 AI 个人助理用处不大。我一年也就点五次外卖，根本不需要它代劳……<strong>我真正觉得它好用的地方是，它可以自动收集和处理网上的大量数据</strong>。它能快速扫描 1000 个 YouTube 频道，找到匹配我兴趣的视频。&quot; <ul><li><strong>这句话精准命中了外脑的正确定位</strong>：个人助理（订外卖/收发邮件）是伪需求；<strong>&quot;大规模信息收集 + 处理&quot;才是真需求</strong>——正是本知识库在做的事。</li></ul></li><li><strong>stratechery.com</strong>：&quot;几乎所有人都夸大了中国模型对美国模型公司的威胁，其实那只是<strong>美国模型供不应求</strong>的结果。&quot; —— 与本期文章 4（&quot;AI 竞赛变得尴尬&quot;/DeepSeek 开源成果）构成一个值得两边都记的辩题：<strong>降价到底是&quot;被开源打下来&quot;还是&quot;供需错位&quot;？</strong> 不做定论，两条并存。</li><li><strong>《尽情享用每一份三明治》</strong>：一位晚期癌症艺术家被问&quot;对生死有什么新理解&quot;，答：&quot;你知道吗，吃三明治是一件多享受的事情……<strong>时刻提醒自己要珍惜每一份三明治，每一分钟，以及所有的一切。</strong>&quot;</li></ol><hr><h2 id="八、跨主题关联" tabindex="-1">八、跨主题关联 <a class="header-anchor" href="#八、跨主题关联" aria-label="Permalink to &quot;八、跨主题关联&quot;">​</a></h2><table tabindex="0"><thead><tr><th>本期内容</th><th>库内已有主题/文件</th></tr></thead><tbody><tr><td>Jev：LLM 输出浮点数 / 决策模型 / typed output</td><td><code>ai-system-architecture/llm-reasoning-verification-thermodynamic.md</code>、<code>llm-scaling-limits.md</code></td></tr><tr><td>Jev 浮点数掩盖判断依据（黑箱回归 / 偏见）</td><td><code>ai-system-architecture/brain-self-evolution.md</code>（打分器分不清&quot;助手凑数&quot;与&quot;助手实质&quot;）、<code>cognitive-atrophy-knowledge.md</code></td></tr><tr><td>Jev 用于搜索重排（BM25 + 精排）</td><td><code>topics/ai-brain/knowledge-system-arsenal.md</code>、<code>ai-system-architecture/deepseek-harness-agent-runtime.md</code></td></tr><tr><td>Markdown 正在变成源码 / prompt 即资产</td><td><code>ai-system-architecture/llm-wiki-gbrain-knowledge-paradigm.md</code>（Compiled Truth + Timeline）、<code>gear-shaft-org-reinvention.md</code></td></tr><tr><td>Markdown in /src 的局部性（无&quot;远处的规格&quot;）</td><td><code>ai-system-architecture/weekly-413-analysis.md</code>（代码即债务 / 糊状千层面）</td></tr><tr><td>不能摄像的摄像头（连续信号→摘要→无法验证）</td><td><code>ai-system-architecture/cognitive-atrophy-knowledge.md</code>、<code>llm-reasoning-verification-thermodynamic.md</code></td></tr><tr><td>RSA-896：LLM 作为工程杠杆移植 CADO-NFS 到 GPU</td><td><code>topics/cybersecurity/</code>、<code>llm-reasoning-verification-thermodynamic.md</code></td></tr><tr><td>加密下限该按&quot;对手有数据中心 GPU&quot;设</td><td><code>topics/cybersecurity/pentagi-autonomous-pentest.md</code></td></tr><tr><td>AI 爬虫抽空公开内容价值链（作家下线）</td><td><code>weekly-412-analysis.md</code>、<code>ai-industry-2026-q3-knowledge.md</code></td></tr><tr><td>个人助理是伪需求，信息收集处理才是真需求</td><td><code>topics/ai-brain/</code>、<code>ai-system-architecture/llm-wiki-gbrain-knowledge-paradigm.md</code></td></tr><tr><td>大公司利润率向基建层集中</td><td><code>ai-system-architecture/ai-industry-2026-q3-knowledge.md</code>、<code>llm-cache-pricing.md</code></td></tr><tr><td>古籍 + AI 解读 / 3D 画廊 / AI 油画</td><td><code>topics/design/</code>、<code>topics/culture/</code></td></tr><tr><td>私有 Skill 仓库（skillsgist）</td><td><code>topics/ai-brain/knowledge-system-arsenal.md</code>、<code>topics/ai-brain/</code>（Hermes skills 体系）</td></tr></tbody></table><hr><h2 id="九、一句话判断" tabindex="-1">九、一句话判断 <a class="header-anchor" href="#九、一句话判断" aria-label="Permalink to &quot;九、一句话判断&quot;">​</a></h2><p><strong>本期主线：AI 的下一步不是&quot;更会说话&quot;，而是&quot;把判断变成一个数&quot;——接口退让换来可编程，代价是可解释性被抹平。</strong></p><ul><li>主文一（Jev）是<strong>接口革命</strong>：把开放生成压成一次分类/打分，让&quot;以前无法数字化的判断&quot;进入可编程世界；但 Willison 的批评点破了代价——<strong>浮点数不会报错，它只会把偏见藏得好好的</strong>（他的城市打分实验就是活证据）。这与本库 replay_eval 的教训同构：<strong>一个分数掩盖了它该被追问的依据。</strong></li><li>主文二（Markdown in /src）是<strong>接口革命的对偶</strong>：Jev 把输出变成数，Gross 把输入变成可 diff 的源码——<strong>两端都在把&quot;模糊的意图/判断&quot;逼成&quot;可版本化、可审查的文本&quot;。</strong> 这直接是本知识库外脑的立身之本。</li><li>两条简讯（不能摄像的摄像头 / RSA-896）是同一句话的两面：<strong>前者：丢了原始信号，验证就不可能；后者：原始门槛（工程）被 LLM 打下来，只剩算力。</strong></li><li>对你直接有用的三件：<strong>skillsgist（私有 Skill 分发思路）、yovoice（把知识转语音）、Video Transcript（视频→字幕→外脑）</strong>；自托管线加 <strong>open-compute（去 Cloudflare 化，Apache-2.0）</strong>。提醒两条：<strong>自托管先查许可证</strong>（EdgeChat 是 GPL-3.0）、<strong>极新项目先借思路别上生产</strong>（skillsgist 2 周 / Burrow 10 天）。</li><li>最该记的一句是 Rauschmayer 的下线声明：<strong>AI 爬虫正在把&quot;免费公开的知识&quot;变成净亏损</strong>——这反过来证明外脑的价值：<strong>私有的、被人消费的 Markdown，才是 AI 时代不会被吸干的知识形态。</strong></li></ul><hr><p>关键词：阮一峰, 科技爱好者周刊, Jev, TypeSafe AI, 决策模型, System One, 概率输出, 浮点数, 是非题, 评分题, 分类任务, 搜索重排, reranking, 黑箱, 偏见, Simon Willison, Markdown, 源码, Markdown in /src, AGENTS.md, Carson Gross, htmx, 局部性, 智能家居摄像头, RSA, RSA-896, 因数分解, CADO-NFS, GPU, Anthropic, 密码安全, AI 爬虫, 内容价值链, 个人助理, 网页抓取, skillsgist, yovoice, open-compute, Video Transcript, 自托管, 许可证, GPL, 英伟达, 利润率</p><p>关联：weekly-413-analysis.md、weekly-412-analysis.md、weekly-402-analysis.md、llm-reasoning-verification-thermodynamic.md、llm-scaling-limits.md、brain-self-evolution.md、cognitive-atrophy-knowledge.md、llm-wiki-gbrain-knowledge-paradigm.md、gear-shaft-org-reinvention.md、deepseek-harness-agent-runtime.md、ai-industry-2026-q3-knowledge.md、llm-cache-pricing.md、topics/ai-brain/knowledge-system-arsenal.md、topics/cybersecurity/pentagi-autonomous-pentest.md、topics/design/、topics/culture/</p>',56)])])}const q=o(s,[["render",a]]);export{h as __pageData,q as default};
